-- Generated by node scripts/generate-notebook-migration.js from the original notebook configs.
insert into public.guided_notebooks (slug, description, node_id, pending_node_slug, config)
select 'internet-browser', 'Segui il percorso dall''indirizzo e dalla risoluzione DNS fino a HTTP, HTML, CSS, JavaScript e ai pixel mostrati dal browser.', n.id,
  case when n.id is null then 'internet-browser' else null end,
  convert_from(decode('', 'base64'), 'UTF8')::jsonb
from (select 1) seed left join public.nodes n on n.slug = 'internet-browser'
on conflict (slug) do nothing;

